param([string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot 'out/build'};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot);$checks=0;$service=$null;$provider=$null
Add-Type -Path (Join-Path $PSScriptRoot 'NativeChatTest.cs')
function Check($Condition,$Name){if(!$Condition){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=25){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 25};try{@{reactions=(Api '/api/reactions/status');playback=(Api '/api/playback');chat=(Api '/api/chat');capabilities=(Api '/api/capabilities')}|ConvertTo-Json -Depth 40|Set-Content "$root/timeout.json"}catch{};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer reaction-fixture'};TimeoutSec=10};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 35 -Compress))};Invoke-RestMethod @a}
function Plan($Responses,$File='plan.json'){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Responses)}|ConvertTo-Json -Depth 40|Set-Content "$providerRoot/$File" -Encoding utf8}
function Plugin($Name,$Arguments){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Wait-For {$script:pluginResult=Api '/api/plugin/result';$script:pluginResult.state-in@('succeeded','failed','paused')} $Name;return $script:pluginResult.result.result}
function Speech{(Api '/api/capabilities').plugins.Where({$_.id-eq'tts'})[0].current}
function Reaction-Policy($Chance,$Gap){$settings=(Api '/api/dashboard').settings;$settings.plugins.widget.reactionProbability=$Chance;$settings.plugins.widget.reactionCooldownMs=$Gap;$null=Api '/api/settings' @{settings=$settings}}
function Health{Invoke-RestMethod ($fixture+'/fixture/health')}
function Drag{ $position=(Api '/api/capabilities').plugins.Where({$_.id-eq'widget'})[0].current;$x=[int]($position.x*($screen.right-112)+56);$y=[int]($position.y*($screen.bottom-112)+56);$dx=if($x-lt$screen.right/2){30}else{-30};$null=[ChatWindowTest]::Send($widget,0x201,0,($y-shl16)-bor$x);$null=[ChatWindowTest]::Send($widget,0x200,1,($y-shl16)-bor($x+$dx));$null=[ChatWindowTest]::Send($widget,0x202,0,($y-shl16)-bor($x+$dx)) }
function Start-App{Remove-Item "$root/ready.json" -ErrorAction SilentlyContinue;$script:service=Start-Process "$BuildRoot/hibernation-agent.exe" -ArgumentList ('--desktop --config "'+$root+'/config.json" --ready-file "'+$root+'/ready.json"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/service.log" -RedirectStandardError "$root/error.log";Wait-For {if($service.HasExited){throw 'desktop exited'};Test-Path "$root/ready.json"} 'backend';$script:origin='http://127.0.0.1:'+((Get-Content "$root/ready.json" -Raw|ConvertFrom-Json).port);Wait-For {$script:widget=[ChatWindowTest]::Find($service.Id,'HibernationDinosaurOverlay');$script:main=[ChatWindowTest]::Find($service.Id,'HibernationConversationV2');$widget-ne[IntPtr]::Zero-and$main-ne[IntPtr]::Zero} 'own native windows';$null=[ChatWindowTest]::Send($main,0x10);$null=[ChatWindowTest]::SetThreadDpiAwarenessContext([IntPtr](-4));$script:screen=New-Object ChatWindowTest+Rect;$null=[ChatWindowTest]::GetClientRect($widget,[ref]$script:screen)}
function Stop-App{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'reaction worker shuts down cleanly'}
$root=Join-Path $ProjectRoot ('artifacts/interaction-reactions-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null;$providerRoot="$root/provider"
$env:HIBERNATION_SESSION_KEY='reaction-fixture';$env:HIBERNATION_REACTION_KEY='synthetic-model-key';$env:TEMP="$BuildRoot/tmp";$env:TMP=$env:TEMP
try{
 $provider=Start-Process "$BuildRoot/Hibernation_TestProvider.exe" -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/provider.log" -RedirectStandardError "$root/provider-error.log";Wait-For {Test-Path "$providerRoot/port"} 'provider';$fixture='http://127.0.0.1:'+(Get-Content "$providerRoot/port")
 $batch=@{version=1;reactions=@('脚下的位置换了。','嗯，这里也可以。','让我自己站一会儿。','刚才那一步不算我走的。','这次落脚挺稳。','先停在这里吧。')|ForEach-Object {@{text=$_;animation='curious'}}};Plan @(@{response=$batch});Plan @(@{response=@{decision='approve';reason='ok';guidance=''};delay_ms=400}) 'review-plan.json'
 $cfg=Get-Content "$ProjectRoot/config/example.json" -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot="$root/data";$cfg.characterRoot="$ProjectRoot/character";$cfg.uiRoot="$ProjectRoot/ui";$cfg.pluginRoot="$BuildRoot/plugins";$cfg.solitudeIntervalMs=600000;$cfg.idleBeforeSolitudeMs=600000;$cfg.maxStartsPerHour=1000;$cfg.plugins=@{widget=@{enabled=$true;roam=$false;reactionCacheEnabled=$true;reactionCooldownMs=250;reactionProbability=1};tts=@{enabled=$true;backend='http';origin=$fixture;path='/v1/audio/speech';volume=0;autoSpeak=$true;maxSeconds=5}};$cfg.review=@{enabled=$true;profileId='reviewer';maxRewrites=1};foreach($item in @(@{id='fixture';model='fixture-model'},@{id='reviewer';model='fixture-reviewer'})){$cfg.profiles+=@{id=$item.id;label=$item.id;enabled=$true;protocol='chat-completions';origin=$fixture;basePath='/v1';model=$item.model;credentialEnvironment='HIBERNATION_REACTION_KEY';timeoutMs=10000;maxOutputTokens=2048}};$cfg|ConvertTo-Json -Depth 40|Set-Content "$root/config.json" -Encoding utf8
 Start-App;$null=Api '/api/model' @{id='fixture'};$null=Api '/api/reactions/refill' @{};Wait-For {(Api '/api/reactions/status').available-eq6} 'six reviewed text and audio candidates';$status=Api '/api/reactions/status';$speech=Speech
 Check ($status.review_ms-ge350-and$status.intent_mode-eq'cache_only') 'slow manager is kept off the gesture playback path';Check ($speech.started_count-eq0-and$speech.prepared_count-eq6) 'background synthesis is silent';Check ((Health).audio_calls-eq6-and(Health).calls-eq2) 'one actor batch and one review prepare six audio clips'
 Reaction-Policy 0 250;Drag;Start-Sleep -Milliseconds 350;Check ((Api '/api/reactions/status').available-eq6-and(Speech).started_count-eq0) 'zero probability skips without consuming a candidate';Reaction-Policy 1 4500;
 $timer=[Diagnostics.Stopwatch]::StartNew();Drag;Wait-For {$script:playback=Api '/api/playback';@($playback.replies.PSObject.Properties|Where-Object {$_.Name.StartsWith('drag-reply')-and$_.Value.state-eq'speaking'}).Count-eq1} 'cached speech start';$elapsed=$timer.ElapsedMilliseconds;$first=@($playback.replies.PSObject.Properties|Where-Object {$_.Name.StartsWith('drag-reply')})[0].Name;$speech=Speech
 Check ($elapsed-lt400) "prepared reaction starts without a network roundtrip (${elapsed}ms)";Check ($speech.prepared_hits-eq1-and$speech.last_synthesis_ms-eq0-and(Health).audio_calls-eq6) 'drag consumes PCM instead of synthesizing again';Check ((Api '/api/reactions/status').available-eq5) 'consumed candidate is removed once';Drag;Start-Sleep -Milliseconds 350;Check ((Api '/api/reactions/status').available-eq5) 'drag while speaking is ignored without consuming another reaction'
 Wait-For {(Api '/api/playback').replies.$first.state-eq'completed'} 'first audio end';Start-Sleep -Milliseconds 400;Check ((Speech).started_count-eq1) 'ignored drag never becomes delayed speech';Drag;Start-Sleep -Milliseconds 100;Check ((Api '/api/reactions/status').available-eq5-and(Speech).started_count-eq1) 'cooldown still blocks a drag after previous speech has ended';Reaction-Policy 1 250;Start-Sleep -Milliseconds 1400;Drag;Wait-For {(Speech).started_count-eq2} 'second cached reaction';Check ((Api '/api/reactions/status').available-eq4-and(Health).calls-eq2) 'second reaction consumes another candidate without a model call';Wait-For {!(Speech).active} 'second audio end';Check ((Api '/api/chat').messages.Count-eq0) 'ambient reactions do not flood the conversation history'
 Stop-App;Start-App;Wait-For {(Api '/api/reactions/status').available-eq4} 'unused reactions restored and audio rewarmed';Check ((Speech).started_count-eq0-and(Health).calls-eq2) 'restart preserves consumption and silently restores only unused candidates'
 for($i=0;$i-lt4;$i++){Drag;Wait-For {(Speech).started_count-eq($i+1)} 'next distinct reaction';Wait-For {!(Speech).active} 'cached audio finishes';Start-Sleep -Milliseconds 50};Check ((Api '/api/reactions/status').available-eq0) 'all six candidates are single use';$calls=(Health).calls;$audioCalls=(Health).audio_calls;Drag;Start-Sleep -Milliseconds 500;Check ((Speech).started_count-eq4-and(Health).calls-eq$calls-and(Health).audio_calls-eq$audioCalls) 'empty cache skips the gesture without late speech or on demand synthesis'
 Plan @(@{response='not a valid reaction batch'});$null=Api '/api/reactions/refill' @{};Wait-For {(Api '/api/reactions/status').last_error-eq'reaction_format'} 'malformed batch rejected';Check ((Api '/api/reactions/status').available-eq0) 'invalid model output creates no usable reaction'
 Plan @(@{response=@{version=1;reactions=@(@{text='这条等待中的反应不应抢占交谈。';animation='idle'})};delay_ms=1800},@{response=@{version=1;kind='reply';text='先聊你刚才说的事。';calls=@()}});$null=Api '/api/reactions/refill' @{};Wait-For {(Api '/api/reactions/status').generating} 'slow prefetch begins';Start-Sleep -Milliseconds 100;$timer.Restart();$null=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text='现在开始交谈'};Wait-For {!(Api '/api/chat').busy-and(Api '/api/chat').messages.Count-eq2} 'foreground chat';Check ($timer.ElapsedMilliseconds-lt1600) 'foreground conversation cancels and overtakes background preparation';Wait-For {!(Api '/api/reactions/status').generating} 'cancelled prefetch settles';Check ((Api '/api/reactions/status').available-eq0) 'cancelled generation never becomes a delayed reaction'
 Stop-App;@{completed=$true;checks=$checks;firstReactionMs=$elapsed;reviewMs=$status.review_ms;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content "$root/acceptance.json";Write-Output "Reaction integration passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
